export function demoHeadshotObjectKey(index: number): string {
  const n = (index % DEMO_HEADSHOT_COUNT) + 1;
  return `demo/headshots/${String(n).padStart(3, "0")}.jpg`;
}

export function demoHeadshotJpeg(index: number): Uint8Array {
  const encoded = DEMO_HEADSHOT_JPEGS[index % DEMO_HEADSHOT_COUNT]!;
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
